def solve(payload):
    sensitive = {"password", "token", "api_key", "secret"}
    def redact(value):
        if isinstance(value, dict):
            return {key: "[REDACTED]" if key.casefold() in sensitive else redact(item) for key, item in value.items()}
        if isinstance(value, list):
            return [redact(item) for item in value]
        return value
    return redact(payload["document"])

